class UploadQuota:
    def __init__(self, monthly_limit_mib: float) -> None:
        if monthly_limit_mib < 0:
            raise ValueError("Monthly limit cannot be negative.")
        # 1 MiB = 1024 * 1024 bytes = 1,048,576 bytes
        self.limit_bytes = int(monthly_limit_mib * 1024 * 1024)
        # Tracks files uploaded per month: {month: {file_name: size_bytes}}
        self._monthly_uploads: dict[str, dict[str, int]] = {}

    def upload(self, name: str, size_bytes: int, month: str) -> None:
        """month is a string like '2026-01'."""
        if size_bytes <= 0:
            raise ValueError("File size must be strictly positive.")

        month_data = self._monthly_uploads.setdefault(month, {})

        # If already uploaded in the same month, it does not count again
        if name in month_data:
            return

        current_used = sum(month_data.values())
        if current_used + size_bytes > self.limit_bytes:
            raise ValueError("Upload exceeds the monthly quota limit.")

        month_data[name] = size_bytes

    def delete(self, name: str, month: str) -> None:
        """Deleting a file does not give back quota in the current month."""
        # Deletion does not alter the quota usage for the month,
        # so historical counted uploads are retained.
        pass

    def used_bytes(self, month: str) -> int:
        """How many bytes count towards the quota in the given month."""
        return sum(self._monthly_uploads.get(month, {}).values())
```

